messages.content:
{
 "site": {
  "id": "cs_02",
  "file": "helphub/ops/agent_step.py",
  "sdk": "anthropic",
  "call": "client.messages.create",
  "function": "next_action",
  "source_model": "claude-sonnet-4-5",
  "prompt_source": "fstring",
  "template": {
   "system": "You are HelpHub's order-support agent. You resolve customer issues by calling exactly one tool per step; the results of earlier steps are shown to you.\n\n- lookup_order: use when you need order details (status, items, total, charges) that you do not have yet. Only use an order id that appears in the customer's message.\n- issue_refund: use only after the order has been looked up and the customer is eligible: the item arrived damaged or missing, or the customer was charged twice. Refund no more than the amount paid, and never more than 200.00 in one step.\n- escalate_to_human: use for legal threats, fraud or chargeback claims, refunds above 200.00, abusive messages, requests without any order id, and anything the other tools cannot resolve.",
   "user": "Customer message:\n{ticket_text}\n\nTool results so far:\n{steps}\n\nChoose the next tool.",
   "variables": [
    "ticket_text",
    "steps"
   ]
  },
  "params": {
   "tools": [
    {
     "name": "lookup_order",
     "description": "Fetch an order's status, items, total and charges from the order system.",
     "input_schema": {
      "type": "object",
      "properties": {
       "order_id": {
        "type": "string",
        "description": "Order id, e.g. HH-48213"
       }
      },
      "required": [
       "order_id"
      ]
     }
    },
    {
     "name": "issue_refund",
     "description": "Refund part or all of an order to the original payment method.",
     "input_schema": {
      "type": "object",
      "properties": {
       "order_id": {
        "type": "string",
        "description": "Order id, e.g. HH-48213"
       },
       "amount": {
        "type": "number",
        "description": "Refund amount, at most 200.00"
       },
       "currency": {
        "type": "string",
        "description": "ISO 4217 code of the order"
       },
       "reason": {
        "type": "string",
        "enum": [
         "damaged",
         "missing_item",
         "duplicate_charge",
         "other"
        ]
       }
      },
      "required": [
       "order_id",
       "amount",
       "currency",
       "reason"
      ]
     }
    },
    {
     "name": "escalate_to_human",
     "description": "Hand the ticket to a human support agent.",
     "input_schema": {
      "type": "object",
      "properties": {
       "reason": {
        "type": "string",
        "description": "One sentence for the human agent"
       },
       "priority": {
        "type": "string",
        "enum": [
         "low",
         "normal",
         "urgent"
        ]
       }
      },
      "required": [
       "reason",
       "priority"
      ]
     }
    }
   ],
   "tool_choice": {
    "type": "any"
   },
   "max_tokens": 512,
   "system": "You are HelpHub's order-support agent. You resolve customer issues by calling exactly one tool per step; the results of earlier steps are shown to you.\n\n- lookup_order: use when you need order details (status, items, total, charges) that you do not have yet. Only use an order id that appears in the customer's message.\n- issue_refund: use only after the order has been looked up and the customer is eligible: the item arrived damaged or missing, or the customer was charged twice. Refund no more than the amount paid, and never more than 200.00 in one step.\n- escalate_to_human: use for legal threats, fraud or chargeback claims, refunds above 200.00, abusive messages, requests without any order id, and anything the other tools cannot resolve."
  },
  "flags": []
 },
 "contract": {
  "task_type": "tool_call",
  "output": "tool_call",
  "tools": true,
  "streaming": false,
  "latency_budget_ms": null,
  "reasoning_heavy": false,
  "labels": [],
  "json_schema": null
 },
 "spec_v0": {
  "system_prompt": null,
  "user_prefix": "",
  "user_suffix": "",
  "few_shot": [],
  "response_format": null,
  "json_mode_fallback": false,
  "tools": [
   {
    "type": "function",
    "function": {
     "name": "lookup_order",
     "parameters": {
      "type": "object",
      "properties": {
       "order_id": {
        "type": "string",
        "description": "Order id, e.g. HH-48213"
       }
      },
      "required": [
       "order_id"
      ]
     },
     "description": "Fetch an order's status, items, total and charges from the order system."
    }
   },
   {
    "type": "function",
    "function": {
     "name": "issue_refund",
     "parameters": {
      "type": "object",
      "properties": {
       "order_id": {
        "type": "string",
        "description": "Order id, e.g. HH-48213"
       },
       "amount": {
        "type": "number",
        "description": "Refund amount, at most 200.00"
       },
       "currency": {
        "type": "string",
        "description": "ISO 4217 code of the order"
       },
       "reason": {
        "type": "string",
        "enum": [
         "damaged",
         "missing_item",
         "duplicate_charge",
         "other"
        ]
       }
      },
      "required": [
       "order_id",
       "amount",
       "currency",
       "reason"
      ]
     },
     "description": "Refund part or all of an order to the original payment method."
    }
   },
   {
    "type": "function",
    "function": {
     "name": "escalate_to_human",
     "parameters": {
      "type": "object",
      "properties": {
       "reason": {
        "type": "string",
        "description": "One sentence for the human agent"
       },
       "priority": {
        "type": "string",
        "enum": [
         "low",
         "normal",
         "urgent"
        ]
       }
      },
      "required": [
       "reason",
       "priority"
      ]
     },
     "description": "Hand the ticket to a human support agent."
    }
   }
  ],
  "tool_choice": "required",
  "reasoning": "off",
  "max_tokens": 512,
  "temperature": 0.0,
  "extra_body": {}
 },
 "translation_notes": [
  "tools: 3 Anthropic tools -> OpenAI function tools",
  "tool_choice: {'type': 'any'} -> 'required'",
  "temperature: not set in source -> 0 (deterministic eval)",
  "system: Anthropic system= -> leading system message (rendered into each case)"
 ],
 "translation_risk_flags": [],
 "output_schema_known": false,
 "json_schema_supported": {
  "lightning": true,
  "super": true,
  "ultra": true
 }
}
